cards.solution:
const akun = {
  info() {
    return `${this.username} (${this.peran})`;
  },
};
const admin = Object.create(akun);
admin.username = "lingga";
admin.peran = "admin";
console.log(admin.info());
console.log(`Punya info sendiri: ${Object.hasOwn(admin, "info")}`);
